19	func newWhyCmd() *cobra.Command {
20		cmd := &cobra.Command{
21			Use:    "why [path]",
22			Short:  "Explain why a file looks the way it does",
23			Hidden: true,
24			Args:   cobra.MaximumNArgs(1),
25			RunE: func(cmd *cobra.Command, args []string) error {
26				var path string
27				if len(args) > 0 {
28					path = args[0]
29				}
30				if path != "" && !canRunWhyTUI(cmd.OutOrStdout()) {
31					cleanup := initWhyLogging(cmd.Context())
32					defer cleanup()
33				}
34				return runWhy(cmd.Context(), cmd.OutOrStdout(), path)
35			},
36		}
37	
38		return cmd
39	}
40	
41	func runWhy(ctx context.Context, w io.Writer, path string) (err error) {
42		ctx, span := perf.Start(ctx, "why",
43			slog.String("path", path),
44			slog.Bool("has_path", path != ""))
45		defer func() {
46			span.RecordError(err)
47			span.End()
48		}()
49	
50		_, modeSpan := perf.Start(ctx, "detect_mode")
51		canUseTUI := canRunWhyTUI(w)
52		modeSpan.End()
53		if path == "" {
54			if !canUseTUI {
55				return errors.New("path required when not running interactively")
56			}
57			return errors.New("interactive file browser is not implemented yet")
58		}
59	
60		_, resolveSpan := perf.Start(ctx, "resolve_path")
61		repoRoot, gitPath, _, err := resolveWhyPath(ctx, path)
62		if err != nil {
63			resolveSpan.RecordError(err)
64			resolveSpan.End()
65			return err
66		}
67		resolveSpan.End()
68	
69		data, err := loadWhyViewData(ctx, repoRoot, gitPath)
70		if err != nil {
71			return err
72		}
73	
74		if canUseTUI {
75			_, renderSpan := perf.Start(ctx, "render_tui")
76			if err := runWhyTUI(ctx, w, data); err != nil {
77				renderSpan.RecordError(err)
78				renderSpan.End()
79				return err
80			}
81			renderSpan.End()
82			return nil
83		}
84	
85		_, renderSpan := perf.Start(ctx, "render_static")
86		content := renderWhyStatic(data)
87		renderSpan.End()
88	
89		_, outputSpan := perf.Start(ctx, "write_output")
90		outputExplainContent(w, content, false)
91		outputSpan.End()
92		return nil
93	}
94	
95	var canRunWhyTUI = defaultCanRunWhyTUI
96	
97	func defaultCanRunWhyTUI(w io.Writer) bool {
98		return !IsAccessibleMode() && interactive.IsTerminalWriter(w) && interactive.CanPromptInteractively()
99	}
100	
101	func initWhyLogging(ctx context.Context) func() {
102		if _, err := paths.WorktreeRoot(ctx); err != nil {
103			return func() {}
104		}
105		logging.SetLogLevelGetter(GetLogLevel)
106		if err := logging.Init(ctx, ""); err != nil {
107			return func() {}
108		}
109		return logging.Close
110	}
111	
112	func resolveWhyPath(ctx context.Context, input string) (string, string, string, error) {
113		repoRoot, err := paths.WorktreeRoot(ctx)
114		if err != nil {
115			return "", "", "", fmt.Errorf("not a git repository: %w", err)
116		}
117		repoRoot = normalizeWhyPathForRel(repoRoot)
118	
119		absPath := input
120		if !filepath.IsAbs(absPath) {
121			absPath, err = filepath.Abs(absPath)
122			if err != nil {
123				return "", "", "", fmt.Errorf("resolving path %q: %w", input, err)
124			}
125		}
126		absPath = normalizeWhyPathForRel(absPath)
127	
128		relPath, err := filepath.Rel(repoRoot, absPath)
129		if err != nil {
130			return "", "", "", fmt.Errorf("resolving path %q relative to repository: %w", input, err)
131		}
132		if relPath == "." || strings.HasPrefix(relPath, ".."+string(filepath.Separator)) || relPath == ".." {
133			return "", "", "", fmt.Errorf("path %q is outside the repository", input)
134		}
135	
136		return repoRoot, filepath.ToSlash(relPath), absPath, nil
137	}
138	
139	func normalizeWhyPathForRel(path string) string {
140		cleaned := filepath.Clean(path)
141		if resolved, err := filepath.EvalSymlinks(cleaned); err == nil {
142			return resolved
143		}
144		dir := filepath.Dir(cleaned)
145		base := filepath.Base(cleaned)
146		if resolvedDir, err := filepath.EvalSymlinks(dir); err == nil {
147			return filepath.Join(resolvedDir, base)
148		}
149		return cleaned
150	}
151	
152	func loadWhyViewData(ctx context.Context, repoRoot, gitPath string) (whyViewData, error) {
153		_, blameSpan := perf.Start(ctx, "git_blame")
154		blameOutput, err := runGitBlame(ctx, repoRoot, gitPath)
155		if err != nil {
156			blameSpan.RecordError(err)
157			blameSpan.End()
158			return whyViewData{}, err
159		}
160		blameSpan.End()
161	
162		_, parseSpan := perf.Start(ctx, "parse_blame")
163		lines, err := parseBlamePorcelain(blameOutput)
164		if err != nil {
165			parseSpan.RecordError(err)
166			parseSpan.End()
167			return whyViewData{}, fmt.Errorf("parse git blame output: %w", err)
168		}
169		parseSpan.End()
170	
171		_, buildRowsSpan := perf.Start(ctx, "build_rows")
172		rows := buildWhyBlameRows(lines)
173		buildRowsSpan.End()
174	
175		_, openRepoSpan := perf.Start(ctx, "open_repository")
176		repo, err := openRepository(ctx)
177		if err != nil {
178			openRepoSpan.RecordError(err)
179			openRepoSpan.End()
180			return whyViewData{}, fmt.Errorf("open repository: %w", err)
181		}
182		openRepoSpan.End()
183	
184		enrichCtx, enrichSpan := perf.Start(ctx, "enrich_commits")
185		commits := enrichWhyCommits(enrichCtx, repo, lines)
186		enrichSpan.End()
187	
188		return whyViewData{
189			GitPath: gitPath,
190			Rows:    rows,
191			Commits: commits,
192		}, nil
193	}
