1	package cli
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/hex"
7		"fmt"
8		"os/exec"
9		"strconv"
10		"strings"
11		"time"
12	)
13	
14	type whyBlameLine struct {
15		CommitHash   string
16		OriginalLine int
17		FinalLine    int
18		Author       string
19		AuthorTime   time.Time
20		Filename     string
21		Source       string
22	}
23	
24	type whyBlameRow struct {
25		whyBlameLine
26	}
27	
28	type whyBlameMetadata struct {
29		Author     string
30		AuthorTime time.Time
31		Filename   string
32	}
33	
34	func runGitBlame(ctx context.Context, repoRoot, gitPath string) ([]byte, error) {
35		cmd := exec.CommandContext(ctx, "git", "blame", "--porcelain", "--", gitPath)
36		cmd.Dir = repoRoot
37	
38		var stdout, stderr bytes.Buffer
39		cmd.Stdout = &stdout
40		cmd.Stderr = &stderr
41	
42		if err := cmd.Run(); err != nil {
43			details := strings.TrimSpace(stderr.String())
44			if details == "" {
45				return nil, fmt.Errorf("git blame failed for %s: %w", gitPath, err)
46			}
47			return nil, fmt.Errorf("git blame failed for %s: %w: %s", gitPath, err, details)
48		}
49	
50		return stdout.Bytes(), nil
51	}
52	
53	func parseBlamePorcelain(data []byte) ([]whyBlameLine, error) {
54		if len(data) == 0 {
55			return nil, nil
56		}
57	
58		rawLines := bytes.Split(bytes.TrimSuffix(data, []byte{'\n'}), []byte{'\n'})
59		metadataByCommit := make(map[string]whyBlameMetadata)
60		lines := make([]whyBlameLine, 0)
61	
62		var current *whyBlameLine
63		for lineNumber, raw := range rawLines {
64			line := strings.TrimSuffix(string(raw), "\r")
65	
66			if hash, originalLine, finalLine, ok, err := parseBlameHeader(line); err != nil {
67				return nil, fmt.Errorf("parse blame header on line %d: %w", lineNumber+1, err)
68			} else if ok {
69				if current != nil {
70					return nil, fmt.Errorf("blame record for %s:%d missing source line", current.CommitHash, current.FinalLine)
71				}
72				next := whyBlameLine{
73					CommitHash:   hash,
74					OriginalLine: originalLine,
75					FinalLine:    finalLine,
76				}
77				if metadata, exists := metadataByCommit[hash]; exists {
78					applyBlameMetadata(&next, metadata)
79				}
80				current = &next
81				continue
82			}
83	
84			if current == nil {
85				if strings.TrimSpace(line) == "" {
86					continue
87				}
88				return nil, fmt.Errorf("blame metadata without header on line %d", lineNumber+1)
89			}
90	
91			if strings.HasPrefix(line, "\t") {
92				current.Source = strings.TrimPrefix(line, "\t")
93				lines = append(lines, *current)
94				metadataByCommit[current.CommitHash] = metadataFromBlameLine(*current)
95				current = nil
96				continue
97			}
98	
99			if err := applyBlameMetadataLine(current, line); err != nil {
100				return nil, fmt.Errorf("parse blame metadata on line %d: %w", lineNumber+1, err)
101			}
102			metadataByCommit[current.CommitHash] = metadataFromBlameLine(*current)
103		}
104	
105		if current != nil {
106			return nil, fmt.Errorf("blame record for %s:%d missing source line", current.CommitHash, current.FinalLine)
107		}
108	
109		return lines, nil
110	}
111	
112	func parseBlameHeader(line string) (string, int, int, bool, error) {
113		fields := strings.Fields(line)
114		if len(fields) < 3 || !isBlameHash(fields[0]) {
115			return "", 0, 0, false, nil
116		}
117	
118		originalLine, err := strconv.Atoi(fields[1])
119		if err != nil {
120			return "", 0, 0, false, fmt.Errorf("invalid original line %q", fields[1])
121		}
122		finalLine, err := strconv.Atoi(fields[2])
123		if err != nil {
124			return "", 0, 0, false, fmt.Errorf("invalid final line %q", fields[2])
125		}
126	
127		return fields[0], originalLine, finalLine, true, nil
128	}
129	
130	func isBlameHash(value string) bool {
131		if len(value) < 7 || len(value)%2 != 0 {
132			return false
133		}
134		_, err := hex.DecodeString(value)
135		return err == nil
136	}
137	
138	func applyBlameMetadataLine(line *whyBlameLine, metadata string) error {
139		switch {
140		case strings.HasPrefix(metadata, "author "):
141			line.Author = strings.TrimPrefix(metadata, "author ")
142		case strings.HasPrefix(metadata, "author-time "):
143			raw := strings.TrimPrefix(metadata, "author-time ")
144			seconds, err := strconv.ParseInt(raw, 10, 64)
145			if err != nil {
146				return fmt.Errorf("invalid author-time %q", raw)
147			}
148			line.AuthorTime = time.Unix(seconds, 0)
149		case strings.HasPrefix(metadata, "filename "):
150			line.Filename = strings.TrimPrefix(metadata, "filename ")
151		}
152		return nil
153	}
154	
155	func metadataFromBlameLine(line whyBlameLine) whyBlameMetadata {
156		return whyBlameMetadata{
157			Author:     line.Author,
158			AuthorTime: line.AuthorTime,
159			Filename:   line.Filename,
160		}
161	}
162	
163	func applyBlameMetadata(line *whyBlameLine, metadata whyBlameMetadata) {
164		line.Author = metadata.Author
165		line.AuthorTime = metadata.AuthorTime
166		line.Filename = metadata.Filename
167	}
168	
169	func buildWhyBlameRows(lines []whyBlameLine) []whyBlameRow {
170		rows := make([]whyBlameRow, len(lines))
171		for i, line := range lines {
172			rows[i] = whyBlameRow{whyBlameLine: line}
173		}
174		return rows
175	}
