1	package cli
2	
3	import (
4		"context"
5		"fmt"
6		"io"
7		"strings"
8		"unicode/utf8"
9	
10		"charm.land/bubbles/v2/key"
11		"charm.land/bubbles/v2/viewport"
12		tea "charm.land/bubbletea/v2"
13		"charm.land/lipgloss/v2"
14		"github.com/go-git/go-git/v6/plumbing"
15	)
16	
17	type whyTUIStyles struct {
18		statusStyles
19	
20		bold        lipgloss.Style
21		dim         lipgloss.Style
22		time        lipgloss.Style
23		author      lipgloss.Style
24		commit      lipgloss.Style
25		lineNo      lipgloss.Style
26		checkpoint  lipgloss.Style
27		columnHead  lipgloss.Style
28		headerLabel lipgloss.Style
29		headerValue lipgloss.Style
30		helpKey     lipgloss.Style
31		helpSep     lipgloss.Style
32	}
33	
34	type whyTUIModel struct {
35		data     whyViewData
36		selected int
37		viewport viewport.Model
38		styles   whyTUIStyles
39		width    int
40		height   int
41	
42		lineWidth int
43	}
44	
45	const (
46		whyTUICheckpointMaxWidth = 12
47		whyTUIHeaderLabelWidth   = 11
48		whyTUISelectedBackground = "\x1b[48;5;236m"
49		whyTUIReset              = "\x1b[0m"
50		whyTUIResetShort         = "\x1b[m"
51		whyTUIResetHyperlink     = "\x1b]8;;\x07"
52		whyTUICommitURLPrefix    = "https://entire.io/gh/entireio/cli/commit/"
53	)
54	
55	var runWhyTUI = defaultRunWhyTUI
56	
57	func defaultRunWhyTUI(ctx context.Context, w io.Writer, data whyViewData) error {
58		ss := newStatusStyles(w)
59		m := newWhyTUIModel(data, ss)
60		p := tea.NewProgram(m, tea.WithContext(ctx))
61		if _, err := p.Run(); err != nil {
62			return fmt.Errorf("why TUI: %w", err)
63		}
64		return nil
65	}
66	
67	func newWhyTUIModel(data whyViewData, ss statusStyles) whyTUIModel {
68		if ss.width <= 0 {
69			ss.width = 60
70		}
71	
72		m := whyTUIModel{
73			data:      data,
74			viewport:  viewport.New(viewport.WithWidth(ss.width), viewport.WithHeight(1)),
75			styles:    newWhyTUIStyles(ss),
76			width:     ss.width,
77			lineWidth: whyLineColumnWidth(data.Rows),
78		}
79		return m.refreshViewport()
80	}
81	
82	func newWhyTUIStyles(ss statusStyles) whyTUIStyles {
83		s := whyTUIStyles{statusStyles: ss}
84		if !ss.colorEnabled {
85			return s
86		}
87	
88		s.bold = lipgloss.NewStyle().Bold(true)
89		s.dim = lipgloss.NewStyle().Faint(true)
90		s.lineNo = lipgloss.NewStyle().Foreground(lipgloss.Color("245"))
91		s.time = lipgloss.NewStyle().Foreground(lipgloss.Color("245"))
92		s.author = lipgloss.NewStyle().Foreground(lipgloss.Color("252"))
93		s.commit = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
94		s.checkpoint = lipgloss.NewStyle().Foreground(lipgloss.Color("245"))
95		s.columnHead = lipgloss.NewStyle().Foreground(lipgloss.Color("245")).Bold(true)
96		s.headerLabel = lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")).Bold(true)
97		s.headerValue = lipgloss.NewStyle().Foreground(lipgloss.Color("252"))
98		s.helpKey = lipgloss.NewStyle().Foreground(lipgloss.Color("245")).Bold(true)
99		s.helpSep = lipgloss.NewStyle().Foreground(lipgloss.Color("241"))
100		return s
101	}
102	
103	func (m whyTUIModel) Init() tea.Cmd {
104		return nil
105	}
106	
107	func (m whyTUIModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea interface
108		switch msg := msg.(type) {
109		case tea.WindowSizeMsg:
110			if msg.Width == m.width && msg.Height == m.height {
111				return m, nil
112			}
113			m.width = msg.Width
114			m.height = msg.Height
115			m.viewport.SetWidth(msg.Width)
116			m = m.refreshViewport()
117			return m, nil
118		case tea.KeyPressMsg:
119			return m.updateKey(msg)
120		}
121		return m, nil
122	}
123	
124	func (m whyTUIModel) updateKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) { //nolint:ireturn // bubbletea pattern
125		switch {
126		case key.Matches(msg, keys.Quit), key.Matches(msg, keys.Back):
127			return m, tea.Quit
128		case key.Matches(msg, keys.Up):
129			if m.selected > 0 {
130				m.selected--
131				m = m.ensureSelectedVisible()
132			}
133		case key.Matches(msg, keys.Down):
134			if m.selected < len(m.data.Rows)-1 {
135				m.selected++
136				m = m.ensureSelectedVisible()
137			}
138		case key.Matches(msg, keys.Home):
139			m.selected = 0
140			m.viewport.GotoTop()
141		case key.Matches(msg, keys.End):
142			if len(m.data.Rows) > 0 {
143				m.selected = len(m.data.Rows) - 1
144				m.viewport.GotoBottom()
145			}
146		}
147		return m, nil
148	}
149	
150	func (m whyTUIModel) View() tea.View {
151		v := tea.View{AltScreen: true}
152		if m.width == 0 {
153			return v
154		}
155	
156		var b strings.Builder
157		b.WriteString(m.renderHeader())
158		b.WriteString(m.renderColumnHeader())
159		b.WriteString(m.renderViewport())
160		b.WriteString("\n")
161		b.WriteString(m.renderFooter())
162		v.SetContent(b.String())
163		return v
164	}
165	
166	func (m whyTUIModel) renderViewport() string {
167		view := m.viewport.View()
168		selectedLine := m.selected - m.viewport.YOffset()
169		if selectedLine < 0 || selectedLine >= m.viewport.Height() {
170			return view
171		}
172	
173		lines := strings.Split(view, "\n")
174		if selectedLine >= len(lines) {
175			return view
176		}
177	
178		lines[selectedLine] = m.renderSelectedViewportLine(lines[selectedLine])
179		return strings.Join(lines, "\n")
180	}
181	
182	func (m whyTUIModel) renderSelectedViewportLine(line string) string {
183		line = markWhyTUISelectedLine(line)
184		if !m.styles.colorEnabled {
185			return line
186		}
187		line += strings.Repeat(" ", max(m.width-lipgloss.Width(line), 0))
188		line = strings.ReplaceAll(line, whyTUIReset, whyTUIReset+whyTUISelectedBackground)
189		line = strings.ReplaceAll(line, whyTUIResetShort, whyTUIResetShort+whyTUISelectedBackground)
190		return whyTUISelectedBackground + line + whyTUIReset
191	}
192	
193	func markWhyTUISelectedLine(line string) string {
194		if line == "" {
195			return ">"
196		}
197	
198		prefixLen := leadingSGRLen(line)
199		if prefixLen >= len(line) {
200			return line + ">"
201		}
202		if line[prefixLen] == ' ' {
203			return line[:prefixLen] + ">" + line[prefixLen+1:]
204		}
205		return line[:prefixLen] + ">" + line[prefixLen:]
206	}
207	
208	func leadingSGRLen(s string) int {
209		offset := 0
210		for offset < len(s) && s[offset] == '\x1b' {
211			if offset+1 >= len(s) || s[offset+1] != '[' {
212				break
213			}
214			end := strings.IndexByte(s[offset:], 'm')
215			if end < 0 {
216				break
217			}
218			offset += end + 1
219		}
220		return offset
221	}
222	
223	func (m whyTUIModel) refreshViewport() whyTUIModel {
224		headerHeight := strings.Count(m.renderHeader(), "\n") + strings.Count(m.renderColumnHeader(), "\n")
225		vpHeight := m.height - headerHeight - 1
226		if vpHeight < 1 {
227			vpHeight = 1
228		}
229	
230		m.viewport.SetWidth(m.width)
231		m.viewport.SetHeight(vpHeight)
232		m.viewport.SetContent(m.renderRows())
233		return m.ensureSelectedVisible()
234	}
235	
236	func (m whyTUIModel) ensureSelectedVisible() whyTUIModel {
237		if len(m.data.Rows) == 0 || m.viewport.Height() <= 0 {
238			return m
239		}
240		if m.selected < m.viewport.YOffset() {
241			m.viewport.SetYOffset(m.selected)
242			return m
243		}
244		bottom := m.viewport.YOffset() + m.viewport.Height() - 1
245		if m.selected > bottom {
246			m.viewport.SetYOffset(m.selected - m.viewport.Height() + 1)
247		}
248		return m
249	}
250	
251	func (m whyTUIModel) renderHeader() string {
252		if len(m.data.Rows) == 0 {
253			return fitWhyTUILine(m.styles.render(m.styles.bold, m.data.GitPath)+" has no blame lines\n", m.width)
254		}
255	
256		row := m.data.Rows[m.selected]
257		info := m.commitInfoForRow(row)
258	
259		title := fmt.Sprintf("%s:%d", m.data.GitPath, row.FinalLine)
260		metadata := strings.Join([]string{
261			m.renderHeaderCommitField(row),
262			m.renderHeaderField("author", whyStaticAuthor(row)),
263			m.renderHeaderField("date", whyStaticTime(row)),
264			m.renderHeaderField("checkpoint", whyStaticCheckpoint(info)),
265		}, "  ")
266		return fitWhyTUILine(title, m.width) + "\n" + fitWhyTUILine(metadata, m.width) + "\n\n"
267	}
268	
269	func (m whyTUIModel) renderHeaderCommitField(row whyBlameRow) string {
270		label := whyColumn("COMMIT:", whyTUIHeaderLabelWidth)
271		value := m.renderCommitHash(whyStaticCommit(row), row.CommitHash, m.styles.headerValue)
272		return m.styles.render(m.styles.headerLabel, label) + " " + value
273	}
274	
275	func (m whyTUIModel) renderHeaderField(label, value string) string {
276		label = whyColumn(strings.ToUpper(label)+":", whyTUIHeaderLabelWidth)
