420	func fitWhyTUILine(line string, width int) string {
421		if width <= 0 {
422			return ""
423		}
424		if lipgloss.Width(line) <= width {
425			return line
426		}
427		return cutWhyTUILine(line, width)
428	}
429	
430	func cutWhyTUILine(line string, width int) string {
431		var b strings.Builder
432		visibleWidth := 0
433		sawSGR := false
434		sawHyperlink := false
435	
436		for i := 0; i < len(line); {
437			if line[i] == '\x1b' {
438				next, isSGR, isHyperlink := consumeWhyTUIEscape(line, i)
439				sawSGR = sawSGR || isSGR
440				sawHyperlink = sawHyperlink || isHyperlink
441				b.WriteString(line[i:next])
442				i = next
443				continue
444			}
445	
446			r, size := utf8.DecodeRuneInString(line[i:])
447			if r == utf8.RuneError && size == 0 {
448				break
449			}
450			runeWidth := lipgloss.Width(string(r))
451			if visibleWidth+runeWidth > width {
452				if sawSGR {
453					b.WriteString(whyTUIReset)
454				}
455				if sawHyperlink {
456					b.WriteString(whyTUIResetHyperlink)
457				}
458				return b.String()
459			}
460			b.WriteRune(r)
461			visibleWidth += runeWidth
462			i += size
463		}
464		return b.String()
465	}
466	
467	func consumeWhyTUIEscape(line string, start int) (int, bool, bool) {
468		if start+1 >= len(line) {
469			return start + 1, false, false
470		}
471		switch line[start+1] {
472		case '[':
473			return consumeWhyTUICSI(line, start), true, false
474		case ']':
475			return consumeWhyTUIOSC(line, start), false, true
476		default:
477			return start + 1, false, false
478		}
479	}
480	
481	func consumeWhyTUICSI(line string, start int) int {
482		for i := start + 2; i < len(line); i++ {
483			if line[i] >= 0x40 && line[i] <= 0x7e {
484				return i + 1
485			}
486		}
487		return len(line)
488	}
489	
490	func consumeWhyTUIOSC(line string, start int) int {
491		for i := start + 2; i < len(line); i++ {
492			if line[i] == '\a' {
493				return i + 1
494			}
495			if line[i] == '\x1b' && i+1 < len(line) && line[i+1] == '\\' {
496				return i + 2
497			}
498		}
499		return len(line)
500	}
