145	// IsInfrastructurePath returns true if the path is part of CLI infrastructure
146	// (i.e., inside the .entire directory)
147	func IsInfrastructurePath(path string) bool {
148		return IsSubpath(EntireDir, path)
149	}
150	
151	// IsSubpath reports whether child is lexically under parent (or equal to it).
152	// It uses filepath.Rel, which cleans both inputs and is traversal-resistant:
153	// a crafted child like "/a/b/../../../etc/passwd" that escapes parent will
154	// produce a relative path starting with ".." and be rejected.
155	func IsSubpath(parent, child string) bool {
156		rel, err := filepath.Rel(parent, child)
157		if err != nil {
158			return false
159		}
160		return rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
161	}
