163	// ToRelativePath converts an absolute path to relative.
164	// Returns empty string if the path is outside the working directory.
165	func ToRelativePath(absPath, cwd string) string {
166		absPath = normalizeMSYSPath(absPath)
167		cwd = normalizeMSYSPath(cwd)
168	
169		// On Windows, MSYS/Git Bash sometimes omits the drive letter, producing
170		// paths like /Users/... that filepath.IsAbs doesn't recognize. Prepend
171		// the drive letter from cwd so filepath.Rel can match them.
172		if runtime.GOOS == osWindows && len(absPath) > 0 && absPath[0] == '/' && len(cwd) >= 2 && cwd[1] == ':' {
173			absPath = cwd[:2] + absPath
174		}
175	
176		if !filepath.IsAbs(absPath) {
177			return absPath
178		}
179		relPath, err := filepath.Rel(cwd, absPath)

