11	func TestParseBlamePorcelain(t *testing.T) {
12		t.Parallel()
13	
14		const blame = `aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa 1 1 2
15	author Alice Example
16	author-time 1714560000
17	filename dir/file with spaces.go
18		package main
19	aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa 2 2
20			fmt.Println("hi")
21	bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb 1 3 1
22	author Bob Example
23	author-time 1714560600
24	filename dir/file with spaces.go
25		func done() {}
26	`
27	
28		lines, err := parseBlamePorcelain([]byte(blame))
29		if err != nil {
30			t.Fatalf("parseBlamePorcelain() error = %v", err)
31		}
32		if len(lines) != 3 {
33			t.Fatalf("parsed %d lines, want 3", len(lines))
34		}
35	
36		first := lines[0]
37		if first.CommitHash != "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa" {
38			t.Fatalf("first commit = %q", first.CommitHash)
39		}
40		if first.OriginalLine != 1 {
41			t.Fatalf("first original line = %d, want 1", first.OriginalLine)
42		}
43		if first.FinalLine != 1 {
44			t.Fatalf("first final line = %d, want 1", first.FinalLine)
45		}
46		if first.Author != "Alice Example" {
47			t.Fatalf("first author = %q", first.Author)
48		}
49		if first.AuthorTime.Unix() != 1714560000 {
50			t.Fatalf("first author time = %d, want 1714560000", first.AuthorTime.Unix())
51		}
52		if first.Filename != "dir/file with spaces.go" {
53			t.Fatalf("first filename = %q", first.Filename)
54		}
55		if first.Source != "package main" {
56			t.Fatalf("first source = %q", first.Source)
57		}
58	
59		second := lines[1]
60		if second.Author != "Alice Example" {
61			t.Fatalf("second author = %q, want repeated metadata", second.Author)
62		}
63		if second.AuthorTime.Unix() != 1714560000 {
64			t.Fatalf("second author time = %d, want repeated metadata", second.AuthorTime.Unix())
65		}
66		if second.Filename != "dir/file with spaces.go" {
67			t.Fatalf("second filename = %q, want repeated metadata", second.Filename)
68		}
69		if second.Source != "\tfmt.Println(\"hi\")" {
70			t.Fatalf("second source = %q, want leading tab preserved", second.Source)
71		}
72	
73		third := lines[2]
74		if third.CommitHash != "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb" {
75			t.Fatalf("third commit = %q", third.CommitHash)
76		}
77		if third.OriginalLine != 1 {
78			t.Fatalf("third original line = %d, want 1", third.OriginalLine)
79		}
80		if third.FinalLine != 3 {
81			t.Fatalf("third final line = %d, want 3", third.FinalLine)
82		}
83		if third.Author != "Bob Example" {
84			t.Fatalf("third author = %q", third.Author)
85		}
86	}
