104	func parseBlameHeader(line string) (string, int, int, bool, error) {
105		fields := strings.Fields(line)
106		if len(fields) < 3 || !isBlameHash(fields[0]) {
107			return "", 0, 0, false, nil
108		}
109	
110		originalLine, err := strconv.Atoi(fields[1])
111		if err != nil {
112			return "", 0, 0, false, fmt.Errorf("invalid original line %q", fields[1])
113		}
114		finalLine, err := strconv.Atoi(fields[2])
115		if err != nil {
116			return "", 0, 0, false, fmt.Errorf("invalid final line %q", fields[2])
117		}
118	
119		return fields[0], originalLine, finalLine, true, nil
120	}
121	
122	func isBlameHash(value string) bool {
123		if len(value) < 7 || len(value)%2 != 0 {
124			return false
125		}
126		_, err := hex.DecodeString(value)
127		return err == nil
128	}
