130	func applyBlameMetadataLine(line *whyBlameLine, metadata string) error {
131		switch {
132		case strings.HasPrefix(metadata, "author "):
133			line.Author = strings.TrimPrefix(metadata, "author ")
134		case strings.HasPrefix(metadata, "author-time "):
135			raw := strings.TrimPrefix(metadata, "author-time ")
136			seconds, err := strconv.ParseInt(raw, 10, 64)
137			if err != nil {
138				return fmt.Errorf("invalid author-time %q", raw)
139			}
140			line.AuthorTime = time.Unix(seconds, 0)
141		case strings.HasPrefix(metadata, "filename "):
142			line.Filename = strings.TrimPrefix(metadata, "filename ")
143		}
144		return nil
145	}
